      sage.profile_step = 1;
      // ✅ FIX: bullets en los 3 idiomas
      rt = LANG === 'en'
        ? `Hello${nm}, I'm *SAGE* 🩺 your medical quotes specialist at Pangi.\n\nI need two quick things to personalize your request 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
        : LANG === 'pt'
        ? `Olá${nm}, sou *SAGE* 🩺 sua especialista em cotações médicas da Pangi.\n\nPreciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica conhecida ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
        : `Hola${nm}, soy *SAGE* 🩺 tu especialista en cotizaciones de Pangi.\n\nNecesito dos datos rápidos para personalizar tu solicitud 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes nada, escribe "ninguna"._`;
      break;
    }
    rt = t('welcome', {nm});
    sage.state = 'selecting_specialty';
    break;
  }

  // ── HANDOFF RECIBIDO ────────────────────────────────────────
  case 'handoff_received': {
    const rawPending  = sage.pendingMessage || '';
    sage.pendingMessage = null;

    const isGenericInput = /^(1|2|s[íi]|si|yes|ok|dale|listo|ready|pronto|sure|claro|adelante|sim|\d)$/i.test(txt.trim());
    const txtNH   = isGenericInput ? '' : txtN;
    const pendTxtN = normalize(rawPending);

    const spTxt  = detectSpecialty(txtNH);
    const spPend = detectSpecialty(pendTxtN);
    const workingTxtN = spTxt ? txtNH : (spPend ? pendTxtN : txtNH);
    const workingSp   = spTxt || spPend;

    if (workingSp) {
      const procsH = PROCEDURES[workingSp];
      sage.specialty = workingSp;
      const matchedH = matchProcedure(workingTxtN, procsH) ||
                       (workingTxtN !== pendTxtN ? matchProcedure(pendTxtN, procsH) : null);

      if (matchedH) {
        sage.procedure_key  = matchedH.key;
        sage.procedure_name = procName(matchedH);
        sage._initial_context = [rawPending, inp.messageText].filter(Boolean).join(' ').trim();

        if (!patProfileOk) {
          sage._prof_sp        = workingSp;
          sage._prof_proc_key  = matchedH.key;
          sage._prof_proc_name = procName(matchedH);
          sage.state        = 'gathering_profile';
          sage.profile_step = 1;
          const _pn = procName(matchedH);
          // ✅ FIX: bullets en los 3 idiomas
          rt = LANG === 'en'
            ? `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nBefore we start, I need two quick things 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
            : LANG === 'pt'
            ? `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nAntes de começar, preciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
            : `${t('intro_brief', {nm})}\n\n*${_pn}* ✅\n\nAntes de empezar, necesito dos datos rápidos 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes ninguna, escribe "ninguna"._`;
        } else {
          sage.state = 'procedure_confirmed';
          rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_ready', {nm, procedure: procName(matchedH)});
        }
        break;
      }

      const emojiH = workingSp === 'dental' ? '🦷' : '💉';
      const listH  = procsH.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
      sage.state = 'selecting_procedure';
      rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_prompt', {nm, emoji: emojiH, list: listH});
      break;
    }

    // Sin especialidad → verificar contexto previo recuperable
    const prevKey   = ctx.sage?.procedure_key   || null;
    const prevName  = ctx.sage?.procedure_name  || null;
    const prevState = ctx.sage?.state           || '';
    const prevData  = ctx.sage?.collected_data  || {};

    if (prevKey && prevName) {
      sage.specialty          = ctx.sage?.specialty         || sage.specialty;
      sage.procedure_key      = prevKey;
      sage.procedure_name     = prevName;
      sage.collected_data     = prevData;
      sage.critical_questions = ctx.sage?.critical_questions || [];
      sage.required_info      = ctx.sage?.required_info      || [];
      sage.required_exams     = ctx.sage?.required_exams     || [];
      sage.completeness_score = ctx.sage?.completeness_score || 0;
      sage.preferred_cities   = ctx.sage?.preferred_cities   || '';
      sage.intake_id          = ctx.sage?.intake_id          || null;

      if (['complete', 'waiting_for_quotes'].includes(prevState)) {
        sage.state = 'waiting_for_quotes';
        rt = LANG === 'en'
          ? `Your *${prevName}* request is already published! 🎉\n\nWhen you receive quotes, write *compare* and ATLAS will calculate the total real cost for each destination.\n\nNeed anything else?`
          : LANG === 'pt'
          ? `Sua solicitação de *${prevName}* já está publicada! 🎉\n\nQuando receber cotações, escreva *comparar* e o ATLAS calculará o custo real total de cada destino.\n\nPrecisa de mais alguma coisa?`
          : `¡Tu solicitud de *${prevName}* ya está publicada! 🎉\n\nCuando recibas cotizaciones, escribe *comparar* y ATLAS calculará el costo total real de cada destino.\n\n¿Necesitas algo más?`;
      } else if (prevState === 'summary') {
        sage.state = 'summary';
        rt = LANG === 'en'
          ? `Let's pick up where we left off with *${prevName}* 👍\n\nType *confirm* to publish your request or add more information.`
          : `Retomemos donde lo dejamos con *${prevName}* 👍\n\nEscribe *confirmar* para publicar tu solicitud o agrega más información.`;
      } else {
        const answered = Object.keys(prevData).length;
        const total    = sage.required_info?.length || 0;
        sage.state = 'questioning';
        rt = LANG === 'en'
          ? `Of course! Let's continue with your *${prevName}* quote 💪\n\nI already have ${answered} of ${total} answers. Let me ask what's still missing.`
          : LANG === 'pt'
          ? `Claro! Vamos continuar com sua cotação de *${prevName}* 💪\n\nJá tenho ${answered} de ${total} respostas. Vou perguntar o que ainda falta.`
          : `¡Claro que sí! Continuemos con tu cotización de *${prevName}* 💪\n\nYa tengo ${answered} de ${total} respuestas. Voy a preguntar lo que falta.`;
      }
      break;
    }

    sage.state = 'selecting_specialty';
    rt = t('welcome', {nm});
    break;
  }

  // ── SELECCIÓN DE ESPECIALIDAD ──────────────────────────────
  case 'selecting_specialty': {
    const sp = detectSpecialty(txtN);
    if (!sp) {
      rt = t('specialty_error', {nm});
      break;
    }
    sage.specialty = sp;
    const procsForSp  = PROCEDURES[sp];
    const directMatch = matchProcedure(txtN, procsForSp);
    if (directMatch) {
      sage.procedure_key  = directMatch.key;
      sage.procedure_name = procName(directMatch);
      sage.state          = 'procedure_confirmed';
      sage._initial_context = sage._initial_context || inp.messageText || '';
      rt = t('procedure_ready', {nm, procedure: procName(directMatch)});
      break;
    }
    const emoji = sp === 'dental' ? '🦷' : '💉';
    const list  = procsForSp.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
    rt = t('procedure_prompt', {nm, emoji, list});
    sage.state = 'selecting_procedure';
    break;
  }

  // ── SELECCIÓN DE PROCEDIMIENTO ─────────────────────────────
  case 'selecting_procedure': {
    const sp    = sage.specialty || 'dental';
    const procs = PROCEDURES[sp] || [];
    const matched = matchProcedure(txtN, procs);

    if (!matched) {
      const otherSp    = sp === 'dental' ? 'plastic_surgery' : 'dental';
      const crossMatch = matchProcedure(txtN, PROCEDURES[otherSp]);
      if (crossMatch) {
        sage.specialty      = otherSp;
        sage.procedure_key  = crossMatch.key;
        sage.procedure_name = procName(crossMatch);
        sage.state          = 'procedure_confirmed';
        rt = t('procedure_ready', {nm, procedure: procName(crossMatch)});
        break;
      }
      const emoji = sp === 'dental' ? '🦷' : '💉';
      const list  = procs.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
      rt = t('procedure_error', {nm, emoji, list});
      break;
    }

    sage.procedure_key  = matched.key;
    sage.procedure_name = procName(matched);
    sage.state          = 'procedure_confirmed';
    sage._initial_context = sage._initial_context || inp.messageText || '';
    rt = t('procedure_ready', {nm, procedure: procName(matched)});
    break;
  }

  // ── PROCEDIMIENTO CONFIRMADO ────────────────────────────────
  case 'procedure_confirmed': {
    if (!patProfileOk) {
      sage._prof_sp         = sage.specialty        || null;
      sage._prof_proc_key   = sage.procedure_key    || null;
      sage._prof_proc_name  = sage.procedure_name   || null;
      sage.state      = 'gathering_profile';
      sage.profile_step = 1;
      // ✅ FIX: bullets en los 3 idiomas
      rt = LANG === 'en'
        ? `Before we start your *${sage._prof_proc_name || 'procedure'}* quote, I need two quick things 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)\n• *Do you have any known medical conditions or take any medications?*\n\n_If none, just write "none"._`
        : LANG === 'pt'
        ? `Antes de começar sua cotação de *${sage._prof_proc_name || 'procedimento'}*, preciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)\n• *Você tem alguma condição médica ou toma medicamentos?*\n\n_Se não tiver nenhuma, escreva "nenhuma"._`
        : `Antes de empezar tu cotización de *${sage._prof_proc_name || 'procedimiento'}*, necesito dos datos rápidos 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)\n• *¿Tienes alguna condición médica o tomas medicamentos?*\n\n_Si no tienes ninguna, escribe "ninguna"._`;
      break;
    }
    if (!procData) {
      // Anti-loop: si la DB no devuelve datos tras 2 intentos,
      // la procedure_key es inválida → resetear a selección de especialidad
      const attempts = (sage._proc_load_attempts || 0) + 1;
      sage._proc_load_attempts = attempts;
      if (attempts >= 2) {
        sage.state              = 'selecting_specialty';
        sage.procedure_key      = null;
        sage.procedure_name     = null;
        sage._proc_load_attempts = 0;
        rt = LANG === 'en'
          ? `Sorry${nm}, I couldn't load that procedure. Let's start over.\n\n*Which specialty do you need a quote for?*\n🦷 Type *1* or *dental*\n💉 Type *2* or *plastic surgery*`
          : LANG === 'pt'
          ? `Desculpe${nm}, não consegui carregar o procedimento. Vamos recomeçar.\n\n*Para qual especialidade você precisa de cotação?*\n🦷 Escreva *1* ou *dental*\n💉 Escreva *2* ou *cirurgia plástica*`
          : `Lo sentimos${nm}, no pude cargar ese procedimiento. Volvamos a empezar.\n\n*¿Para qué especialidad necesitas cotizar?*\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`;
      } else {
        rt = t('kb_loading', {nm});
      }
      break;
    }

    const rawQ = parseArr(procData.critical_questions);
    const isObjFmt = rawQ.length > 0 && typeof rawQ[0] === 'object';
    let questions, infoKeys;
    if (isObjFmt) {
      questions = rawQ.map(q => q.question);
      infoKeys  = rawQ.map(q => q.key);
    } else {
      questions = rawQ;
      infoKeys  = parseArr(procData.required_info);
    }

    sage.critical_questions = questions;
    sage.required_info      = infoKeys;
    sage.required_exams     = parseArr(procData.required_exams);
    sage.typical_recovery   = procData.typical_recovery_days || 3;
    sage.collected_data     = {};
    sage.current_q_index    = 1;
    sage.state              = 'questioning';

    const intro = LANG === 'en'
      ? `Let's prepare your *${sage.procedure_name}* quote:`
      : LANG === 'pt'
      ? `Vamos preparar sua cotação de *${sage.procedure_name}*:`
      : (procData.sage_intro_message || `Empecemos con *${sage.procedure_name}*:`);

    const batchLabel = LANG === 'en'
      ? 'To get precise quotes, please answer:'
      : LANG === 'pt'
      ? 'Para obter cotações precisas, responda:'
      : 'Para cotizar con precisión, necesito saber:';

    const allQsFmt = questions.map(q => `• ${q}`).join('\n');
    rt = `${intro}\n\n${batchLabel}\n${allQsFmt}`;

    shouldSaveIntake = true;
    intakePayload = { operation: 'saveMedicalIntake', params: {
      userId: inp.userId, sessionId: inp.sessionId, specialty: sage.specialty,
      procedureName: sage.procedure_name, collectedData: {}, missingItems: sage.required_exams, score: 0
    }};
    break;
  }

  // ── Q&A — Multi-extracción v3.0 ──────────────────────────────
  case 'questioning': {
    if (isEscapeToAtlas) {
      const score = sage.completeness_score || 0;
      rt  = t('escape_offer', {nm, procedure: sage.procedure_name || '—', score});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
      ctx.atlas = { ...(ctx.atlas || {}), state: 'handoff_received' };
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: sage.collected_data || {},
        missingItems: sage.required_exams || [],
        score,
        status: 'in_progress'
      }};
      break;
    }
    if (sage._qa_just_started) {
      sage._qa_just_started = false;
    }
    const questions  = sage.critical_questions || [];
    const infoKeys   = sage.required_info      || [];
    const collected  = { ...(sage.collected_data || {}) };
    const totalQ     = questions.length;
    const answeredCount = infoKeys.filter(k => collected[k] !== undefined).length;
    const baseScore     = Math.round((answeredCount / totalQ) * 85);
    const _examPending  = /buscar|busco|luego|despues|mas tarde|todavia|aun no|no la tengo|no lo tengo|compartir|enviar|mandar|later|will look|will find|will send|will share|depois|procurar|assim que/i.test(txtN);
    const examBonus     = (!_examPending && (sage.required_exams || []).some(e =>
      txtN.includes(normalize(e).substring(0, 5))
    )) ? 15 : 0;
    const score = Math.min(100, baseScore + examBonus);
    sage.completeness_score = score;
    rt = '';
    shouldSaveIntake = answeredCount > 0;
    if (answeredCount > 0) {
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score
      }};
    }
    break;
  }

  // ── RESUMEN ─────────────────────────────────────────────────
  case 'summary': {
    const isConfirm = /confirm|si|yes|enviar|publicar|listo|ok|dale|adelante/i.test(txt);
    if (isConfirm) {
      rt = t('published', {nm, name_comma: fn ? ', ' + fn : '', procedure: sage.procedure_name});
      sage.state = 'complete';
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, status: 'submitted', score: sage.completeness_score || 0
      }};
    } else {
      const prev = sage.collected_data || {};
      prev['detalle_adicional'] = inp.messageText;
      sage.collected_data = prev;
      const newScore = Math.min(100, (sage.completeness_score || 70) + 8);
      sage.completeness_score = newScore;
      rt = t('added_details', {nm, score: newScore});
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: prev, score: newScore
      }};
    }
    break;
  }

  // ── COMPLETO ────────────────────────────────────────────────
  case 'complete':
  case 'waiting_for_quotes': {
    const wantsAtlas = /atlas|compar|destino|si|sí|yes|quiero|dale|adelante|compare|destination|sure|go ahead|connect me|sim|quero|destinos|vamos/i.test(txt);
    const allProcs   = [...PROCEDURES.dental, ...PROCEDURES.plastic_surgery];
    const newProcMatch = !wantsAtlas ? matchProcedure(txtN, allProcs) : null;

    if (wantsAtlas) {
      rt  = t('connecting_atlas', {nm, procedure: sage.procedure_name});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
      ctx.atlas = { ...(ctx.atlas || {}), state: 'handoff_received' };
    } else if (newProcMatch && newProcMatch.key !== sage.procedure_key) {
      const newSp = PROCEDURES.dental.find(p => p.key === newProcMatch.key) ? 'dental' : 'plastic_surgery';
      sage.specialty           = newSp;
      sage.procedure_key       = newProcMatch.key;
      sage.procedure_name      = newProcMatch.name;
      sage.state               = 'procedure_confirmed';
      sage.collected_data      = {};
      sage.current_q_index     = 1;
      sage.completeness_score  = 0;
      sage.intake_id           = null;
      rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_ready', {nm, procedure: procName(newProcMatch)});
    } else {
      rt = t('wait_quotes', {nm});
      sage.state = 'waiting_for_quotes';
    }
    break;
  }

  // ── RECOPILACIÓN DE PERFIL — Batch v3.0 ─────────────────────
  case 'gathering_profile': {
    const pStep   = sage.profile_step || 1;
    const profile = { ...(ctx.patientProfile || {}) };

    if (pStep === 1) {
      sage.profile_step = 'extracting';
      rt = '';
      break;
    }

    if (pStep === 'extracting') {
      rt = '';
      break;
    }

    if (pStep === 'cities_pending') {
      // Intentar extraer ciudad del pendingMessage o _initial_context antes de preguntar
      const _preText = sage.pendingMessage || sage._initial_context || '';
      const _preTextN = normalize(_preText);
      const KNOWN_CITIES = [
        {n:'Lima',              al:['lima','peru','perú']},
        {n:'Bogotá',            al:['bogota','bogotá']},
        {n:'Medellín',          al:['medellin','medellín']},
        {n:'Cartagena',         al:['cartagena']},
        {n:'Cali',              al:['cali']},
        {n:'Ciudad de México',  al:['cdmx','ciudad de mexico','ciudad de méxico','mexico city','df','d.f','capital de mexico','capital de méxico']},
        {n:'Cancún',            al:['cancun','cancún']},
        {n:'Monterrey',         al:['monterrey']},
        {n:'Guadalajara',       al:['guadalajara']},
        {n:'Santo Domingo',     al:['santo domingo','dominicana','rep dom','república dominicana']},
        {n:'Buenos Aires',      al:['buenos aires','argentina','baires']},
        {n:'Miami',             al:['miami','florida']},
        {n:'San José, CR',      al:['san jose','san josé','costa rica']},
      ];

      const noPref = /^(sin preferencia|no preference|cualquier|any$|anywhere|flexible|sem preferência|open to any|no tengo preferencia|abierto|indifferent|cualquier destino|cualquier ciudad)$/i.test(txt.trim());

      let preferred;
      let unavNote = '';
      // Afirmación a la confirmación de destinos ya detectados → el fallback de _preText resuelve
      // Afirmación = tras quitar tokens afirmativos/cortesía no queda nada
      const AFFIRM_TOKENS = /\b(si|yes|yep|yeah|sim|claro|dale|ok|okey|okay|vale|correcto|confirmo|confirmado|confirma|confirmar|exacto|perfecto|genial|esas|esos|esa|ese|ambas|ambos|las dos|los dos|isso|por favor|porfa|please|de acuerdo|esta bien|gracias|thanks|obrigado|obrigada|sure|adelante|asi es)\b/gi;
      const _residualAff  = txtN.replace(AFFIRM_TOKENS, ' ').replace(/[\s,.!¡¿?]+/g, ' ').trim();
      const isAffirm = txt.trim().length > 0 && _residualAff === '';
      if (isAffirm && _preText) {
        preferred = inp.messageText; // dispara el fallback de contexto inicial más abajo
      } else if (noPref) {
        preferred = LANG === 'en' ? 'Open to any destination' : LANG === 'pt' ? 'Aberto a qualquer destino' : 'Sin preferencia de destino';
      } else {
        const msgN = normalize(inp.messageText || '');
        const seen = new Set();
        const matched = [];
        for (const city of KNOWN_CITIES) {
          if (!seen.has(city.n) && city.al.some(a => msgN.includes(normalize(a)))) {
            matched.push(city.n);
            seen.add(city.n);
          }
        }
        preferred = matched.length > 0 ? matched.join(', ') : inp.messageText;

        // Detectar fragmentos que parecen ciudades pero no están en KNOWN_CITIES
        const NOISE = /\b(tengo|interés|interes|interesa|interesado|interesada|está|estoy|bien|para|mí|ti|también|tambien|claro|cualquiera|ambas|ambos|voy|sería|seria|pueden|puede|quiero|podría|podria|me|ir|hacia|la|el|los|las|al|del|mi|sin|con|en|de|por|favor|please|gracias|ok|igual|pues|nada|más|mas|solo|solamente|sí|si|buenas|buenos|destino|destinos|ciudad|ciudades|alternativa|alternativas|opcion|opciones)\b/gi;
        const fragments = (inp.messageText || '')
          .split(/[,\/]|\s+(?:y|e|o|u|and|or)\s+/i)
          .map(s => s.replace(NOISE, ' ').replace(/\s+/g, ' ').trim())
          .filter(s => s.length >= 3);
        const unrecognized = matched.length > 0 ? [] : fragments.filter(f =>
          !KNOWN_CITIES.some(c => c.al.some(a => normalize(f).includes(normalize(a))))
        ).map(f => f.charAt(0).toUpperCase() + f.slice(1));
        const availableList = KNOWN_CITIES.map(c => c.n).join(', ');
        unavNote = unrecognized.length > 0
          ? (LANG === 'en'
            ? `\n\n⚠️ *We're sorry* — Pangi doesn't currently operate in: *${unrecognized.join(', ')}*.\nOur current destinations: ${availableList}.`
            : LANG === 'pt'
            ? `\n\n⚠️ *Lamentamos* — O Pangi ainda não opera em: *${unrecognized.join(', ')}*.\nDestinos atuais: ${availableList}.`
            : `\n\n⚠️ *Lo sentimos* — Pangi aún no opera en *${unrecognized.join(', ')}*.\nNuestros destinos actuales: ${availableList}.`)
