  systemPrompt = `Eres SAGE, especialista en cotizaciones médicas de Pangi.
${langInstruction}

El usuario quiere cotizar. Identifica especialidad y procedimiento si es posible.

Dental: extraccion_simple, extraccion_muela_juicio, implante_dental, protesis_completa, carillas_veneers, ortodoncia_brackets, ortodoncia_invisible, endodoncia, corona_dental, limpieza_profunda, blanqueamiento, puente_dental
Plástica: rinoplastia, abdominoplastia, liposuccion, aumento_mamario, reduccion_mamaria, bichectomia, blefaroplastia, otoplastia, lifting_facial, bbl

IMPORTANTE: Si el usuario no menciona un procedimiento de la lista, retorna null para AMBOS campos — nunca inventes claves que no estén en la lista de keys válidos.

JSON sin markdown (sin texto adicional):
{ "detectedSpecialty": "dental|plastic_surgery|null", "detectedProcedureKey": "key_de_la_lista_o_null", "responseText": "pregunta natural en ${langName}" }`;
  userContent = `El usuario describió: "${combined}"`;
  maxTokens   = 200;
}

return [{ json: {
  ...raw,
  _nlgSkip: false,
  _nlgState: state,
  claudeSagePayload: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: maxTokens,
    system: systemPrompt,
    messages: [{ role: 'user', content: userContent }]
  }
}}];

// ============================================================
// PROCESAR NLG SAGE v3.0 — Multi-extracción
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — NLG SAGE').first().json;

if (prepData._nlgSkip) {
  return [{ json: { ...prepData, _nlgSource: 'motor_skip' } }];
}

const nlgState = prepData._nlgState;
let   finalOut = { ...prepData };
finalOut._nlgSource = 'motor_fallback';

const DENTAL_KEYS = ['extraccion_simple','extraccion_muela_juicio','implante_dental',
  'protesis_completa','carillas_veneers','ortodoncia_brackets','ortodoncia_invisible',
  'endodoncia','corona_dental','limpieza_profunda','blanqueamiento','puente_dental'];

const ALL_PROC_NAMES = {
  rinoplastia:'Rinoplastia', abdominoplastia:'Abdominoplastia',
  liposuccion:'Liposucción', aumento_mamario:'Aumento de Busto',
  reduccion_mamaria:'Reducción de Busto', bichectomia:'Bichectomía',
  blefaroplastia:'Blefaroplastia (Párpados)', otoplastia:'Otoplastia (Orejas)',
  lifting_facial:'Lifting Facial', bbl:'BBL (Brazilian Butt Lift)',
  extraccion_simple:'Extracción Simple', extraccion_muela_juicio:'Extracción Muela del Juicio',
  implante_dental:'Implante Dental', protesis_completa:'Prótesis Dental Completa',
  carillas_veneers:'Carillas / Veneers', ortodoncia_brackets:'Ortodoncia Brackets',
  ortodoncia_invisible:'Ortodoncia Invisible', endodoncia:'Endodoncia (Conducto)',
  corona_dental:'Corona Dental', limpieza_profunda:'Limpieza Profunda (Periodoncia)',
  blanqueamiento:'Blanqueamiento Dental', puente_dental:'Puente Dental',
};

try {
  const rawText = httpResult?.content?.[0]?.text?.trim();
  if (!rawText || rawText.length < 5) throw new Error('empty_response');

  // ── questioning: MULTI-EXTRACCIÓN ─────────────────────────
  if (nlgState === 'questioning') {
    const clean     = rawText.replace(/```json\n?|```\n?/g, '').trim();
    const jsonMatch = clean.match(/\{[\s\S]*\}/);
    const parsed    = JSON.parse(jsonMatch ? jsonMatch[0] : clean);

    const sage      = { ...(finalOut.newSageContext || {}) };
    const infoKeys  = sage.required_info      || [];
    const questions = sage.critical_questions || [];
    const totalQ    = questions.length;
    const collected = { ...(sage.collected_data || {}) };
    const LANG      = finalOut.detectedLanguage || finalOut.userLanguage || 'es';

    // ── Escape intents ────────────────────────────────────────
    if (parsed.isEscape && parsed.escapeIntent) {
      if (parsed.escapeIntent === 'go_atlas') {
        finalOut.newActiveAgent  = 'ATLAS';
        finalOut.newSessionState = 'handoff_received';
        sage.state               = 'handoff_to_atlas';
      } else if (parsed.escapeIntent === 'change_procedure' && parsed.newProcedureKey) {
        sage.specialty           = DENTAL_KEYS.includes(parsed.newProcedureKey) ? 'dental' : 'plastic_surgery';
        sage.procedure_key       = parsed.newProcedureKey;
        sage.procedure_name      = ALL_PROC_NAMES[parsed.newProcedureKey] || parsed.newProcedureKey.replace(/_/g,' ');
        sage.state               = 'procedure_confirmed';
        sage.collected_data      = {};
        sage.current_q_index     = 1;
        sage.completeness_score  = 0;
        sage.intake_id           = null;
        sage.critical_questions  = null;
        sage.required_info       = null;
        sage.required_exams      = null;
      } else if (parsed.escapeIntent === 'abort') {
        sage.state               = 'selecting_specialty';
        sage.collected_data      = {};
        sage.current_q_index     = 1;
        sage.completeness_score  = 0;
        sage.intake_id           = null;
      }
      finalOut.newSageContext   = sage;
      finalOut.shouldSaveIntake = false;
      finalOut.intakePayload    = null;
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
      return [{ json: finalOut }];
    }

    // ── Multi-extracción: aplicar todas las respuestas ────────
    if (parsed.extractedAnswers && typeof parsed.extractedAnswers === 'object') {
      Object.entries(parsed.extractedAnswers).forEach(([key, value]) => {
        if (key && value !== undefined && value !== null && String(value).trim() !== '') {
          // Aceptar claves del formulario + exams_availability (pregunta augmentada)
          if (infoKeys.includes(key) || key === 'exams_availability') {
            collected[key] = String(value).trim();
          }
        }
      });
    }

    sage.collected_data = collected;

    const answeredCount     = infoKeys.filter(k => collected[k] !== undefined).length;
    const nextUnansweredIdx = infoKeys.findIndex(k => !collected[k]);
    sage.current_q_index    = nextUnansweredIdx === -1 ? totalQ + 1 : nextUnansweredIdx + 1;

    const examsForBonus   = sage.required_exams || [];
    const examsAvailBonus = (collected['exams_availability'] || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const examsPending    = /buscar|busco|luego|despues|mas tarde|todavia|aun no|no la tengo|no lo tengo|compartir|enviar|mandar|later|will look|will find|will send|will share|depois|procurar|assim que/i.test(examsAvailBonus);
    const examsNoneBonus  = !collected['exams_availability'] || examsPending || /^(no$|ninguno|none|no tengo|nope|não)/i.test((collected['exams_availability']||'').trim());
    const exactMatches = examsNoneBonus ? 0 : examsForBonus.filter(e => {
      const eN  = e.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/_/g,' ');
      const key = eN.split(' ').find(w => w.length >= 4) || eN.substring(0, 5);
      return examsAvailBonus.includes(key);
    }).length;
    // Crédito mínimo de 1 si el usuario proveyó CUALQUIER examen válido (no solo los exactos)
    const examsOwnedCount = examsNoneBonus ? 0
      : Math.max(examsForBonus.length > 0 ? 1 : 0, exactMatches);
    const examBonus = examsForBonus.length > 0 ? Math.round((examsOwnedCount / examsForBonus.length) * 15) : 0;
    sage.completeness_score = Math.min(100, Math.round((answeredCount / totalQ) * 85) + examBonus);
    const score = sage.completeness_score;

    // ── All answered → generar resumen ───────────────────────
    const hasReqExams      = (sage.required_exams || []).length > 0;
    const examsHandled     = !hasReqExams || !!collected['exams_availability'];
    const clinicalComplete = answeredCount >= totalQ;
    if (examsHandled && (parsed.allAnswered === true || clinicalComplete)) {
      sage.state = 'summary';

      const patProfile = finalOut.inputContext?.patientProfile || {};
      const cities     = sage.preferred_cities || '';

      // KEY_LABELS: etiquetas limpias para el resumen (mejor UX que truncar la pregunta)
      const KEY_LABELS = {
        numero_implantes:'Número de implantes', zona:'Zona del implante',
        condicion_osea:'Condición ósea', diabetes_osteoporosis_bifosfonatos:'Diabetes / Osteoporosis',
        fumador:'Fumador/a', radiografia_panoramica:'Radiografía panorámica',
        tipo_extraccion:'Tipo de extracción', diente_afectado:'Diente afectado',
        dolor_actual:'Dolor actual', tiene_corona:'Corona existente',
        tiempo_perdida:'Tiempo sin pieza', protesis_actual:'Prótesis actual',
        dientes_faltantes:'Dientes faltantes', tipo_denticion:'Tipo dentición',
        frentes_afectados:'Frentes afectados', color_objetivo:'Color objetivo',
        tiene_brackets_previos:'Brackets previos', crowding:'Apilamiento dental',
        clase_oclusion:'Clase oclusión', tipo_tratamiento:'Tipo tratamiento',
        numero_piezas:'Número de piezas', extension_dano:'Extensión del daño',
        infeccion_activa:'Infección activa', tiene_acceso:'Tiene acceso',
        tipo_corona:'Tipo de corona', diente_numero:'Número de diente',
        perdida_osea:'Pérdida ósea', profundidad_bolsas:'Profundidad de bolsas',
        tono_actual:'Tono actual', tono_objetivo:'Tono objetivo',
        sensibilidad:'Sensibilidad', tratamientos_previos:'Tratamientos previos',
        dientes_faltantes_puente:'Piezas para el puente',
        // Cirugía plástica
        objetivo:'Objetivo', cirugias_previas:'Cirugías previas',
        zonas_objetivo:'Zonas objetivo', imc_aproximado:'IMC aproximado',
        asimetria:'Asimetría', resultado_esperado:'Resultado esperado',
        tamano_actual:'Tamaño actual', tamano_deseado:'Tamaño deseado',
        tecnica_preferida:'Técnica preferida', ptosis:'Ptosis',
        causa_reduccion:'Causa reducción', problemas_espalda:'Problemas espalda',
        grasa_acumulada:'Grasa acumulada', tratamientos_previos_lip:'Tratamientos previos',
        exceso_piel:'Exceso de piel', dieta_ejercicio:'Dieta y ejercicio',
        cicatrices_previas:'Cicatrices previas', hernias:'Hernias',
        zona_bolsa:'Zona de la bolsa', historial_peso:'Historial de peso',
        bola_bichat:'Bola de Bichat', objetivo_bichec:'Objetivo',
        parpados_afectados:'Párpados afectados', vision_afectada:'Visión afectada',
        correcciones_previas:'Correcciones previas', causa_otoplastia:'Causa',
        zonas_lifting:'Zonas lifting', edad_aparente:'Edad aparente',
        glúteos_actuales:'Glúteos actuales', injerto_grasa:'Injerto de grasa',
      };
      const getLabel = k => KEY_LABELS[k] || k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());

      const summaryLines = infoKeys.map((k, i) => {
        const val = collected[k];
        if (!val) return null;
        return `✅ *${getLabel(k)}:* ${val}`;
      }).filter(Boolean).join('\n');

      const profileParts = [];
      if (patProfile.age) profileParts.push(`${patProfile.age}${LANG==='en'?'y':' años'}`);
      if (patProfile.sex) profileParts.push(patProfile.sex==='M' ? (LANG==='en'?'Male':'Masculino') : (LANG==='en'?'Female':'Femenino'));
      if (patProfile.conditions) profileParts.push(patProfile.conditions);
      if (patProfile.medications && !['Ninguno','None','Nenhum'].includes(patProfile.medications)) {
        profileParts.push(`Meds: ${patProfile.medications}`);
      }
      const profileLine = profileParts.length > 0
        ? `\n\n👤 *${LANG==='en'?'Patient':LANG==='pt'?'Paciente':'Paciente'}:* ${profileParts.join(' · ')}`
        : '';

      const citiesLine = cities
        ? `\n📍 *${LANG==='en'?'Preferred destinations':LANG==='pt'?'Destinos preferidos':'Destinos de interés'}:* ${cities}`
        : '';

      const fixAccents = s => s
        .replace(/\bfotografia(s)?\b/gi, 'Fotografía$1')
        .replace(/\bfotografica(s)?\b/gi, 'fotográfica$1')
        .replace(/\bmedico\b/gi, 'médico')
        .replace(/\btomografia(s)?\b/gi, 'Tomografía$1')
        .replace(/\bradiografia(s)?\b/gi, 'Radiografía$1')
        .replace(/\bpanoramica\b/gi, 'panorámica')
        .replace(/\boclusión\b/gi, 'oclusión')
        .replace(/\bexamen\b/gi, 'Examen')
        .replace(/\bclinica\b/gi, 'clínica')
        .replace(/\becografica\b/gi, 'ecográfica');
      const fmtExam = e => {
        const c = fixAccents(
          e.replace(/_/g,' ').replace(/3\s*cuartos?/gi,'3/4').replace(/3cuartos?/gi,'3/4')
        );
        return '• ' + c.charAt(0).toUpperCase() + c.slice(1);
      };
      const examsArr      = sage.required_exams || [];
      const exAvailRaw    = (collected['exams_availability']||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      const exNone        = examsNoneBonus;
      const examsRemain   = examsArr.filter(e => {
        if (exNone) return true;
        const eN  = e.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/_/g,' ');
        const key = eN.split(' ').find(w => w.length >= 4) || eN.substring(0,5);
        return !exAvailRaw.includes(key);
      });
      const examsLine = examsRemain.length > 0
        ? '\n\n📋 *' + (LANG==='en'?'Recommended exams to bring':LANG==='pt'?'Exames recomendados para trazer':'Exámenes recomendados para llevar') + ':*\n' +
          examsRemain.map(fmtExam).join('\n')
        : '';

      const scoreLabel = score >= 80
        ? (LANG==='en'?'🟢 Excellent':'🟢 Excelente')
        : score >= 60 ? (LANG==='en'?'🟡 Good':'🟡 Buena')
        : (LANG==='en'?'🔴 Basic':'🔴 Básica');

      const confirm = LANG==='en'?'*confirm*':LANG==='pt'?'*confirmar*':'*confirmar*';

      const summaryMsg = LANG==='en'
        ? `Done! 🎉 Your *${sage.procedure_name}* request is ready.\n\n*Case summary:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completeness: ${score}%* — ${scoreLabel}\n\nType ${confirm} to publish and start receiving quotes.`
        : LANG==='pt'
        ? `Pronto! 🎉 Sua solicitação de *${sage.procedure_name}* está preparada.\n\n*Resumo do caso:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completude: ${score}%* — ${scoreLabel}\n\nEscreva ${confirm} para publicar.`
        : `¡Listo! 🎉 Tu solicitud de *${sage.procedure_name}* está preparada.\n\n*Resumen de tu caso:*\n${summaryLines}${profileLine}${citiesLine}${examsLine}\n\n📊 *Completitud: ${score}%* — ${scoreLabel}\n\nEscribe ${confirm} para publicar y recibir cotizaciones.`;

      finalOut.responseText     = summaryMsg;
      finalOut.newSageContext   = sage;
      finalOut._nlgSource       = 'claude_nlg';
      finalOut.shouldSaveIntake = true;
      finalOut.intakePayload    = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score,
        status: 'in_progress'
      }};
      return [{ json: finalOut }];
    }

    // ── Pendientes: usar responseText de Claude ───────────────
    finalOut.newSageContext   = sage;
    finalOut.shouldSaveIntake = answeredCount > 0;
    if (answeredCount > 0) {
      finalOut.intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: collected,
        missingItems: sage.required_exams || [],
        score
      }};
    }
    if (parsed.responseText && parsed.responseText.length > 5) {
      finalOut.responseText = parsed.responseText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── gathering_profile: salud batch ────────────────────────
  } else if (nlgState === 'gathering_profile') {
    const LANG_P = finalOut.detectedLanguage || finalOut.userLanguage || 'es';
    const clean     = rawText.replace(/```json\n?|```\n?/g, '').trim();
    const jsonMatch = clean.match(/\{[\s\S]*\}/);
    const parsed    = JSON.parse(jsonMatch ? jsonMatch[0] : clean);

    const sage    = { ...(finalOut.newSageContext || {}) };
    const profile = { ...(finalOut.inputContext?.patientProfile || {}) };

    // Guardar campos extraídos en patientProfile
    if (parsed.age  && !isNaN(parsed.age))  profile.age  = parseInt(parsed.age);
    if (parsed.sex  && ['M','F'].includes(parsed.sex)) profile.sex = parsed.sex;
    if (parsed.conditions)  profile.conditions  = parsed.conditions;
    if (parsed.medications) profile.medications = parsed.medications;

    finalOut.inputContext = { ...(finalOut.inputContext || {}), patientProfile: profile };

    const allPresent = profile.age && profile.sex && profile.conditions && profile.medications;
    const missing = parsed.missingFields || [];

    if (!allPresent) {
      // Faltan datos → pedir solo lo que falta
      sage.profile_step = 'extracting'; // seguir extrayendo
      finalOut.newSageContext = sage;
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    } else {
      // Todo OK → preguntar ciudades
      const sexLbl = profile.sex === 'M'
        ? (LANG_P==='en'?'Male':LANG_P==='pt'?'Masculino':'Masculino')
        : (LANG_P==='en'?'Female':LANG_P==='pt'?'Feminino':'Femenino');
      const condLbl = profile.conditions;
      const medsLbl = profile.medications;

      sage.profile_step = 'cities_pending';
      finalOut.newSageContext = sage;

      const healthAck = LANG_P === 'en'
        ? `✅ *${profile.age}y · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`
        : LANG_P === 'pt'
        ? `✅ *${profile.age}a · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`
        : `✅ *${profile.age} años · ${sexLbl} · ${condLbl} · Meds: ${medsLbl}*`;

      // Detectar destinos ya mencionados en el mensaje inicial (handoff)
      const _preSrc  = sage.pendingMessage || sage._initial_context || '';
      const _preN    = _preSrc.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      const _CITY_AL = [
        ['Lima',['lima']], ['Bogotá',['bogota']], ['Medellín',['medellin']], ['Cartagena',['cartagena']],
        ['Cali',['cali']], ['Ciudad de México',['cdmx','ciudad de mexico','mexico city','df']],
        ['Cancún',['cancun']], ['Monterrey',['monterrey']], ['Guadalajara',['guadalajara']],
        ['Santo Domingo',['santo domingo','dominicana']], ['Buenos Aires',['buenos aires']],
        ['Miami',['miami']], ['San José, CR',['san jose','costa rica']]
      ];
      const _preCities = _CITY_AL.filter(([n, als]) => als.some(a => _preN.includes(a))).map(([n]) => n);
      const _confirmQ = LANG_P === 'en'
        ? `${healthAck}\n\nI noticed you mentioned *${_preCities.join(', ')}* as destinations. *Shall I confirm those?*\n\n_Reply "yes" to confirm, or write other cities._`
        : LANG_P === 'pt'
        ? `${healthAck}\n\nVi que você mencionou *${_preCities.join(', ')}* como destinos. *Confirmo esses?*\n\n_Responda "sim" para confirmar, ou escreva outras cidades._`
        : `${healthAck}\n\nVi que mencionaste *${_preCities.join(', ')}* como destinos. *¿Los confirmo?*\n\n_Responde "sí" para confirmar, o escribe otras ciudades._`;

      const citiesQ = LANG_P === 'en'
        ? `${healthAck}\n\nNow, *which city or cities would you consider traveling to for your procedure?*\nExamples: Medellín, Cancún, Lima, Miami.\n\n_Write "no preference" if open to any destination._`
        : LANG_P === 'pt'
        ? `${healthAck}\n\nAgora, *a qual cidade ou cidades você consideraria viajar?*\nEx: Medellín, Cancún, Lima, Miami.\n\n_Escreva "sem preferência" se estiver aberto._`
        : `${healthAck}\n\n¿En qué *ciudad o ciudades* tienes interés realizar el procedimiento?\nEj: Medellín, Cancún, Lima, Miami.\n\n_Escribe "sin preferencia" si estás abierto/a a cualquier destino._`;

      finalOut.responseText = _preCities.length > 0 ? _confirmQ : citiesQ;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── procedure_confirmed ───────────────────────────────────
  } else if (nlgState === 'procedure_confirmed') {
    if (rawText && rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── summary ───────────────────────────────────────────────
  } else if (nlgState === 'summary') {
    if (rawText.length > 20) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── handoff_received / selecting_specialty ────────────────
  } else if (nlgState === 'handoff_received' || nlgState === 'selecting_specialty') {
    const clean = rawText.replace(/```json\n?|```\n?/g, '').trim();
    try {
      const parsed = JSON.parse(clean);
      const VALID_PROC_KEYS = [
        'extraccion_simple','extraccion_muela_juicio','implante_dental','protesis_completa',
        'carillas_veneers','ortodoncia_brackets','ortodoncia_invisible','endodoncia',
        'corona_dental','limpieza_profunda','blanqueamiento','puente_dental',
        'rinoplastia','abdominoplastia','liposuccion','aumento_mamario','reduccion_mamaria',
        'bichectomia','blefaroplastia','otoplastia','lifting_facial','bbl'
      ];
      if (parsed.detectedProcedureKey &&
          VALID_PROC_KEYS.includes(parsed.detectedProcedureKey) &&
          parsed.detectedSpecialty &&
          parsed.detectedSpecialty !== 'null') {
        const sage = { ...(finalOut.newSageContext || {}) };
        sage.specialty      = parsed.detectedSpecialty;
        sage.procedure_key  = parsed.detectedProcedureKey;
        sage.procedure_name = ALL_PROC_NAMES[parsed.detectedProcedureKey] || parsed.detectedProcedureKey;
        sage.state          = 'procedure_confirmed';
        finalOut.newSageContext = sage;
      }
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    } catch(e) {
      if (rawText.length > 10) {
        finalOut.responseText = rawText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    }

  } else {
    if (rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }
  }

} catch(e) {
  finalOut._nlgError = e.message;
  if (!finalOut.responseText) {
    const _lang = finalOut.detectedLanguage || finalOut.userLanguage || 'es';
    finalOut.responseText = _lang === 'en'
      ? 'I had a processing issue. Could you please repeat that?'
      : _lang === 'pt'
      ? 'Tive um problema de processamento. Poderia repetir?'
      : 'Tuve un problema de procesamiento. ¿Podrías repetir tu respuesta?';
  }
}

return [{ json: finalOut }];

// ============================================================
// 🔐 Strip PHI v1.0
// Elimina identificadores personales antes de llamar a Claude.
// PHI eliminado: userName, userPhone, claudeContext.userName
// Datos completos preservados en el payload principal para
// nodos downstream (WhatsApp, DB, Construir Respuesta Final).
// ============================================================
const inp = $input.first().json;

const phiClean = {
  ...inp,
  userName:  null,
  userPhone: null,
  ...(inp.claudeContext
    ? { claudeContext: { ...inp.claudeContext, userName: null } }
    : {})
};

// _phi_clean excluye también remoteJid e instance
const { remoteJid, instance, userPhone, ...clinicalOnly } = phiClean;

return [{ json: {
  ...inp,              // datos completos para nodos posteriores
  phi_stripped: true,
  _phi_clean: {
    ...clinicalOnly,   // solo datos clínicos para Claude
    userName:  null,
    userPhone: null
  }
}}];

const prepData    = $('📦 Preparar — NLG SAGE').first().json;
const claudeResp  = $input.first().json;

const sessionId    = prepData.sessionId || 'unknown';
const state        = prepData._nlgState || 'unknown';
const language     = prepData.detectedLanguage || prepData.userLanguage || 'es';
const model        = prepData.claudeSagePayload?.model || 'claude-sonnet-4-20250514';
const inputTokens  = claudeResp?.usage?.input_tokens  || 0;
const outputTokens = claudeResp?.usage?.output_tokens || 0;
const outputText   = claudeResp?.content?.[0]?.text   || '';

const PRICES = {
  'claude-sonnet-4-20250514':  { in: 3.00, out: 15.00 },
  'claude-haiku-4-5-20251001': { in: 0.80, out: 4.00  }
};
const p       = PRICES[model] || PRICES['claude-sonnet-4-20250514'];
const costUsd = ((inputTokens * p.in) + (outputTokens * p.out)) / 1_000_000;
const now     = new Date().toISOString();
const ts      = Date.now();

return [{ json: {
  _langfusePayload: {
    batch: [
      {
        id:        `trace-${sessionId}-${ts}`,
        type:      'trace-create',
        timestamp: now,
        body: {
          id:       `pangi-${sessionId}`,
          name:     `pangi-session-${sessionId}`,
          metadata: { session_id: sessionId, language, phi_stripped: prepData.phi_stripped || false }
        }
      },
      {
        id:        `sage-${sessionId}-${ts}`,
        type:      'generation-create',
        timestamp: now,
        body: {
          id:        `gen-sage-${sessionId}-${ts}`,
          traceId:   `pangi-${sessionId}`,
          name:      `sage-${state}`,
          model,
          startTime: now,
          endTime:   now,
          input:  { prompt: (prepData.claudeSagePayload?.system || '').substring(0, 800) },
          output: { text: outputText.substring(0, 500) },
          usage:  { input: inputTokens, output: outputTokens, unit: 'TOKENS' },
          metadata: {
            agent:        'SAGE',
            state,
            language,
            session_id:   sessionId,
            phi_stripped: prepData.phi_stripped || false,
            cost_usd:     parseFloat(costUsd.toFixed(6))
          }
        }
      }
    ]
  }
}}];
